using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfApp");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: Default discriminator renamed from "Discriminator" to "$type".
        // Preserve the old property name for existing documents.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // Breaking change: id property no longer contains the discriminator prefix.
        // Preserve old compound id format (e.g. "Product|123") for existing documents.
        modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public decimal Price { get; set; }
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // Breaking change: Sync I/O no longer supported on Cosmos DB provider.
    // Synchronous methods like ToList() and SaveChanges() now throw.
    // All queries and saves must use async equivalents.

    // BEFORE (throws in EF Core 9):
    // List<Product> GetProducts(CosmosDbContext db) => db.Products.ToList();
    // void Save(CosmosDbContext db) => db.SaveChanges();

    // AFTER — use async:
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
        => await db.Products.ToListAsync();

    async Task SaveAsync(CosmosDbContext db)
        => await db.SaveChangesAsync();

    async Task<Product?> FindAsync(CosmosDbContext db, string id)
        => await db.Products.FindAsync(id);
}

